def transform(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    out=[[0]*len(grid[0]) for _ in grid]
    # Exact-cover using 2x2 squares and L-triominoes. Search preferring squares,
    # then map each L according to its missing corner in its 2x2 box.
    def pieces(rem):
        if not rem: return []
        r,c=min(rem)
        candidates=[]
        # Square tiles
        for dr,dc in ((0,0),(-1,0),(0,-1),(-1,-1)):
            s={(r+dr+i,c+dc+j) for i in range(2) for j in range(2)}
            if s<=rem: candidates.append((s,1))
        # L triominoes across any 2x2 square
        for ar in range(max(0,r-1),r+1):
          for ac in range(max(0,c-1),c+1):
            box={(ar+i,ac+j) for i in range(2) for j in range(2)}
            for miss in box:
              s=box-{miss}
              if (r,c) in s and s<=rem:
                # missing TL=>2, TR=>3, BL=>4, BR=>2
                color={(ar,ac):2,(ar,ac+1):3,(ar+1,ac):4,(ar+1,ac+1):2}[miss]
                candidates.append((s,color))
        candidates.sort(key=lambda x: 0 if x[1]==1 else 1)
        for s,col in candidates:
            rest=pieces(rem-s)
            if rest is not None: return [(s,col)]+rest
        return None
    tiling=pieces(cells)
    if tiling:
        for s,col in tiling:
            for r,c in s: out[r][c]=col
    return out
